// Emits base.css — the universal MFE entry stylesheet.
//
// tokens.css (emit-tokens-css.mjs) stays pure: literal-only CSS custom
// properties, no selectors, no @-rules beyond :root. It deliberately does
// NOT carry the theme-switchable tokens (canvas/surface/text-*/border/
// divider/border-emphasized/focus/warning-DEFAULT/commons-accent) — see that
// file's header.
//
// Those theme-switchable tokens, together with the font imports, Tailwind
// directives, and the handful of universal (non-token) base rules that used
// to be hand-copied into all 15 MFEs' src/styles/index.css, are exactly what
// base.css supplies instead. An MFE's index.css becomes `@import` of this
// file plus, for the few MFEs that have any, a short tail of genuinely
// MFE-local rules (a feature-unique CSS var, a component-scoped utility
// class) that never belonged in a shared file to begin with.
//
// Every theme-switchable RGB triple below is NORMATIVE FROM tokens.json's
// `$themeValues` (light/dark) on each leaf token — nothing is hardcoded in
// this emitter. Task 5.3 traced 13 of the 15 MFEs' src/styles/index.css to
// byte-identical theme-variable blocks (commons-mfe and kite-mfe were the
// two outliers, converged onto the same values separately) and promoted
// that consensus into tokens.json. The focus-halo box-shadow values are not
// duplicated here either — they're read from the pre-existing
// shadow.cog["focus-light"/"focus-dark"] tokens (Task 2.2), which already
// carried the same values as 11 of 13 MFEs' --cog-focus-halo.
import { leafValue, orderedEntries } from "./tokens.mjs";

// [tokens.json path segments under color.cog, CSS custom-property suffix]
const COG_THEME_VARS = [
  [["canvas"], "canvas"],
  [["surface"], "surface"],
  [["surface-subtle"], "surface-subtle"],
  [["surface-muted"], "surface-muted"],
  [["skeleton"], "skeleton"],
  [["text-primary"], "text-primary"],
  [["text-secondary"], "text-secondary"],
  [["text-tertiary"], "text-tertiary"],
  [["text-eyebrow"], "text-eyebrow"],
  [["warning", "DEFAULT"], "warning"],
  [["border"], "border"],
  [["divider"], "divider"],
  [["border-emphasized"], "border-emphasized"],
  [["focus"], "focus"],
];

function cogNode(tokens, path) {
  let node = tokens.color.cog;
  for (const key of path) node = node[key];
  return node;
}

function themeValues(node) {
  const tv = node.$themeValues;
  if (!tv || typeof tv.light !== "string" || typeof tv.dark !== "string") {
    throw new Error(`Missing $themeValues.{light,dark} on token: ${JSON.stringify(node)}`);
  }
  return tv;
}

/**
 * Build the ordered [varName, {light, dark}] list this emitter renders:
 * the 13 --cog-* theme vars (in COG_THEME_VARS' declared order), then
 * --cog-focus-halo (sourced from shadow.cog focus-light/focus-dark, comma
 * spacing normalized to match the rest of this file's rgba() style), then
 * --commons-accent.
 */
function themeVarEntries(tokens) {
  const entries = COG_THEME_VARS.map(([path, suffix]) => {
    const node = cogNode(tokens, path);
    return [`--cog-${suffix}`, themeValues(node)];
  });

  const focusLight = leafValue(tokens.shadow.cog["focus-light"]).replace(/,(?=\S)/g, ", ");
  const focusDark = leafValue(tokens.shadow.cog["focus-dark"]).replace(/,(?=\S)/g, ", ");
  entries.push(["--cog-focus-halo", { light: focusLight, dark: focusDark }]);

  const commonsAccent = themeValues(tokens.color.commons.accent);
  entries.push(["--commons-accent", commonsAccent]);

  // Gradients as custom properties. theme.extend.backgroundImage only reaches
  // a CLASS, but a gradient is also needed where no class can go: inside a
  // `style` object, and in `border-image`, which has no Tailwind utility at
  // all. Without a var those call sites inline the hex stops, which is token
  // drift no gate can see. Gradients are theme-invariant, so light === dark.
  for (const [name, node] of orderedEntries(tokens.gradient?.cog ?? {})) {
    const value = leafValue(node);
    entries.push([`--cog-${name}-gradient`, { light: value, dark: value }]);
  }

  return entries;
}

function themeBlock(entries, theme, indent) {
  return entries.map(([name, values]) => `${indent}${name}: ${values[theme]};`).join("\n");
}

export function emitBaseCss(tokens) {
  const entries = themeVarEntries(tokens);

  return `/* GENERATED FILE — do not hand-edit.
 * Produced by frontends/design-tokens/generate.mjs from tokens.json.
 * The universal MFE entry stylesheet: the Tailwind directives, the theme-switchable --cog- and --commons-accent CSS
 * custom properties (all three blocks — :root, [data-theme="dark"] and .dark,
 * and the prefers-color-scheme media query — every RGB triple normative
 * from tokens.json's $themeValues), the universal focus-visible/disabled/
 * html/body rules, the .text-balance/.text-pretty utilities, and the
 * reduced-motion fallback.
 *
 * Import this as line 1 of an MFE's src/styles/index.css. Append only
 * genuinely MFE-local rules after it — a feature-unique CSS var, a
 * component-scoped utility class — never another copy of anything above. */

/* NOTE — the @fontsource imports are deliberately NOT emitted here, and must
 * stay in each MFE's own src/styles/index.css.
 *
 * postcss-import resolves a bare specifier relative to the file CONTAINING
 * the @import, not the ultimate consumer. frontends/design-tokens has no
 * package.json (deliberately — the ratchet roster and the CI fan-out globs
 * are both derived from frontends/-star-/package.json, so this directory is
 * fan-out-free), therefore no node_modules, therefore "@fontsource/inter"
 * cannot resolve from here and every consuming MFE's build fails with
 * ENOENT. Giving this directory a package.json to fix that would enrol it in
 * the 17-MFE fan-out and Trivy scan, which is a worse trade.
 *
 * Fonts are a consumer concern anyway: they must resolve from the node_modules
 * of whichever package is being built. Each index.css keeps its own 8 lines
 * (Inter 300/400/500/600/700 + JetBrains Mono 400/500/700, self-hosted from
 * npm rather than fonts.googleapis.com so the CSP stays tight to 'self'). */

@tailwind base;
@tailwind components;
@tailwind utilities;

/* Theme tokens — values are RGB triplets so Tailwind's \`<alpha-value>\`
 * placeholder can compose them. Light is the default; dark mode is
 * activated by setting \`data-theme="dark"\` on <html> (or a \`.dark\` class —
 * both wired in tailwind.config.ts). */
@layer base {
  :root {
${themeBlock(entries, "light", "    ")}
  }

  [data-theme="dark"],
  .dark {
${themeBlock(entries, "dark", "    ")}
  }

  /* Honor system preference when no explicit theme attribute is set. */
  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) {
${themeBlock(entries, "dark", "      ")}
    }
  }

  html {
    color-scheme: light dark;
  }

  body {
    @apply bg-cog-canvas text-cog-text-primary antialiased font-sans text-body-md;
  }

  /* Universal focus-visible ring — 2 px solid outline + 2 px offset.
   * Components are free to override on inputs (focus-within halo, etc.)
   * but this ensures every keyboard-focusable element gets a visible
   * indicator without per-component effort. */
  :where(
    button,
    a,
    [role="button"],
    [role="link"],
    [role="switch"],
    [role="tab"],
    [role="menuitem"],
    [role="option"],
    input,
    select,
    textarea,
    summary,
    [tabindex]:not([tabindex="-1"])
  ):focus-visible {
    outline: 2px solid rgb(var(--cog-focus));
    outline-offset: 2px;
  }

  /* Disabled state — never opacity-only (per design doc §0). */
  :where(button, a, input, select, textarea):disabled,
  :where(button, a, input, select, textarea)[aria-disabled="true"] {
    cursor: not-allowed;
  }
}

@layer utilities {
  .text-balance {
    text-wrap: balance;
  }
  .text-pretty {
    text-wrap: pretty;
  }
}

/* Honor reduced-motion preference — replace transitions with instant
 * state changes. 0.01ms (not 0) lets rAF-based animations complete in one
 * frame rather than hanging. Spec §3a canonical block. */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
`;
}


--- frontends/design-tokens/lib/emit-colors-ts.mjs (80 lines) ---
// ---------------------------------------------------------------------------
// emit-colors-ts.mjs — a TypeScript colour map for RUNTIME consumers.
//
// Canvas, WebGL and inline-SVG code cannot use a utility class: it hands colour
// STRINGS to a drawing API. Those call sites previously hardcoded hex, which is
// token drift no gate could see — a ramp could be recoloured in tokens.json and
// the canvas would keep painting the old value forever.
//
// Two shapes come out of here:
//   * a LITERAL token (`cog-blue-600`) emits its hex directly;
//   * a THEME-AWARE token (`cog-surface`, whose $value is an
//     `rgb(var(--…))` reference) emits an explicit `{ light, dark }` pair,
//     because a canvas has no CSS cascade to resolve the var against — the
//     consumer must pick a side from its own theme state.
// ---------------------------------------------------------------------------
import { orderedEntries } from "./tokens.mjs";

function hexFromTriple(triple) {
  const [r, g, b] = triple.trim().split(/\s+/).map((n) => Number(n));
  const h = (n) => n.toString(16).toUpperCase().padStart(2, "0");
  return `#${h(r)}${h(g)}${h(b)}`;
}

/** Walk color.* and flatten to `cog-…` / `gc-…` / `kn-et-…` utility names. */
function collect(node, prefix, out) {
  for (const [key, child] of orderedEntries(node)) {
    if (child && typeof child === "object" && "$value" in child) {
      const name = prefix ? `${prefix}-${key}` : key;
      const value = child.$value;
      if (typeof value === "string" && value.startsWith("rgb(var(")) {
        const tv = child.$themeValues;
        if (tv?.light && tv?.dark) {
          out.push([name, { light: hexFromTriple(tv.light), dark: hexFromTriple(tv.dark) }]);
        }
        continue; // a var with no theme values has nothing a canvas can use
      }
      if (typeof value === "string") out.push([name, value]);
      continue;
    }
    if (child && typeof child === "object") {
      collect(child, prefix ? `${prefix}-${key}` : key, out);
    }
  }
}

export function emitColorsTs(tokens) {
  const out = [];
  const colors = tokens.color ?? {};
  for (const [group, node] of orderedEntries(colors)) {
    // `color.cog.*` flattens to the `cog-` utility prefix; sibling groups
    // (gc, knEt) already carry their prefix in the leaf key.
    // `color.cog.*` flattens to the `cog-` utility prefix. A sibling group
    // whose leaves already carry their own prefix (gc-*, kn-et-*) must NOT
    // gain a second one, but `commons` does need its group name or its
    // leaves collide with unprefixed keys.
    const firstLeaf = orderedEntries(node)[0]?.[0] ?? "";
    const carriesOwnPrefix = /^(gc|kn)-/.test(firstLeaf);
    collect(node, group === "cog" ? "cog" : carriesOwnPrefix ? "" : group, out);
  }
  out.sort((a, b) => a[0].localeCompare(b[0]));
  const body = out
    .map(([name, v]) =>
      typeof v === "string"
        ? `  ${JSON.stringify(name)}: ${JSON.stringify(v)},`
        : `  ${JSON.stringify(name)}: { light: ${JSON.stringify(v.light)}, dark: ${JSON.stringify(v.dark)} },`,
    )
    .join("\n");
  return `// GENERATED by frontends/design-tokens/generate.mjs — do not edit.
//
// Runtime colour map for consumers that cannot use a utility class (canvas,
// WebGL, inline SVG attributes). A theme-aware token is emitted as an explicit
// { light, dark } pair: a canvas has no cascade to resolve rgb(var(--…)).
export const COG_COLORS = Object.freeze({
${body}
} as const);

export type CogColorName = keyof typeof COG_COLORS;
`;
}


--- frontends/design-tokens/lib/emit-contrast.mjs (40 lines) ---
// Emits contrast.generated.json — WCAG contrast ratios for every literal-hex
// color token in tokens.json against pure white (#FFFFFF, the light-surface
// approximation) and pure black (#000000, the dark-surface approximation).
// Scoped to LITERAL tokens only: the CSS-var-backed surface/text/border
// tokens have no single value (each MFE picks its own RGB triple per theme —
// see emit-tokens-css.mjs's header comment) so there's no fixed pair to rate.
import { orderedEntries, leafValue } from "./tokens.mjs";
import { contrastRatio } from "./contrast-math.mjs";

const HEX_RE = /^#[0-9a-fA-F]{6}$/;

function rate(ratio) {
  return {
    ratio: Math.round(ratio * 100) / 100,
    aaNormalText: ratio >= 4.5,
    aaLargeText: ratio >= 3,
    aaaNormalText: ratio >= 7,
  };
}

export function emitContrast(tokens) {
  const pairs = [];
  for (const [rampName, ramp] of Object.entries(tokens.color.cog)) {
    if (rampName.startsWith("$")) continue;
    if (!ramp || typeof ramp !== "object" || "$value" in ramp) continue; // skip non-ramp leaves
    for (const [stop, node] of orderedEntries(ramp)) {
      const value = leafValue(node);
      if (!HEX_RE.test(value)) continue; // skip CSS-var-backed leaves (DEFAULT, etc.)
      const token = `cog-${rampName}-${stop}`;
      pairs.push({
        token,
        hex: value,
        onWhite: rate(contrastRatio(value, "#FFFFFF")),
        onBlack: rate(contrastRatio(value, "#000000")),
      });
    }
  }
  return { $generated: "frontends/design-tokens/generate.mjs", pairs };
}


--- frontends/design-tokens/lib/emit-manifest.mjs (50 lines) ---
// Emits tokens.manifest.json — a machine-readable index of every token GROUP
// (name, dtcg $type, count of leaves) for a later Claude-facing hook to read
// without having to parse tokens.json's full nested shape itself.
import { orderedEntries } from "./tokens.mjs";

function isLeaf(node) {
  return node && typeof node === "object" && "$value" in node;
}

function countLeaves(node) {
  if (isLeaf(node)) return 1;
  let n = 0;
  for (const [key, value] of Object.entries(node)) {
    if (key.startsWith("$")) continue;
    n += countLeaves(value);
  }
  return n;
}

function walkGroups(node, path, out) {
  if (isLeaf(node)) return;
  const entries = orderedEntries(node);
  const leafEntries = entries.filter(([, v]) => isLeaf(v));
  if (leafEntries.length > 0) {
    out.push({
      path: path.join("."),
      leafCount: leafEntries.length,
      types: [...new Set(leafEntries.map(([, v]) => v.$type))],
    });
  }
  for (const [key, value] of entries) {
    if (!isLeaf(value)) walkGroups(value, [...path, key], out);
  }
}

export function emitManifest(tokens) {
  const groups = [];
  for (const topKey of Object.keys(tokens)) {
    if (topKey.startsWith("$")) continue;
    walkGroups(tokens[topKey], [topKey], groups);
  }
  return {
    $schema: "cogos-design-tokens-manifest@1",
    source: "frontends/design-tokens/tokens.json",
    generatedBy: "frontends/design-tokens/generate.mjs",
    totalLeafTokens: countLeaves(tokens),
    groups,
  };
}


--- frontends/design-tokens/lib/emit-tailwind-mapping.mjs (44 lines) ---
// Emits tailwind-mapping.md — hand-authored prose (Tailwind-version-specific,
// pinned to Tailwind 3.4.19), NOT derived from tokens.json values. Documents
// which `theme.extend.*` key backs which Tailwind utility prefix, and which
// of those axes cn.ts's tailwind-merge config currently understands.
export function emitTailwindMapping() {
  return `# Tailwind axis → utility-prefix mapping

GENERATED FILE HEADER — do not hand-edit the table below without also
updating \`frontends/ui/src/lib/cn.ts\` and/or
\`frontends/design-tokens/lib/emit-twmerge-config.mjs\`. Content is
hand-authored (not derived from tokens.json values) because it documents
Tailwind 3.4.19's own axis semantics, which is why Tailwind is pinned exactly
at that version — a Tailwind major bump can change which classGroup a utility
belongs to.

| \`theme.extend\` key | Utility prefix(es) | cn.ts axis registered? |
|---|---|---|
| \`colors\` (CSS-var tokens) | \`bg-\`, \`text-\`, \`border-\`, \`divider-\`, \`ring-\` | native (color axis) |
| \`colors\` (literal ramps) | \`bg-cog-*\`, \`text-cog-*\`, \`border-cog-*\` | native (color axis) |
| \`fontFamily\` | \`font-\` | native |
| \`fontSize\` | \`text-\` | yes — \`font-size\` axis (custom, since \`text-*\` size utilities collide with the native color axis's \`text-\` prefix) |
| \`spacing\` | \`p-\`, \`m-\`, \`gap-\`, \`top-\`/\`inset-\` (via \`cog-topbar\`), \`w-\`/\`h-\` (via \`cog-switch-thumb-travel\`) | \`top\` axis yes (cog-topbar only); \`p-\`/\`m-\`/\`gap-\` native |
| \`width\` | \`w-\` | yes — \`w\` axis |
| \`borderWidth\` | \`border-\` (width, not color) | yes — \`border-w\` axis |
| \`borderRadius\` | \`rounded-\` | native |
| \`boxShadow\` | \`shadow-\` | yes — \`shadow\` axis (custom, since elevation and shadow-COLOR utilities collide in tailwind-merge's stock config) |
| \`backdropBlur\` | \`backdrop-blur-\` | native |
| \`backgroundImage\` | \`bg-\` (image, not color) | yes — \`bg-image\` axis (custom, else collides with background-color) |
| \`transitionDuration\` | \`duration-\` | native |
| \`transitionTimingFunction\` | \`ease-\` | native |
| \`minHeight\` | \`min-h-\` | native |
| \`minWidth\` | \`min-w-\` | yes — \`w\` axis note: \`min-w-tap\`/\`min-w-cog-toast\` ride the NATIVE \`min-w\` classGroup, distinct from the custom \`w\` axis above (which only covers \`theme.extend.width\`, i.e. \`w-*\`) |
| \`keyframes\` / \`animation\` | \`animate-\` | native |
| \`zIndex\` | \`z-\` | yes — \`z\` axis |

Axes NOT yet registered in cn.ts (Task 2.3 widens cn.ts to consume ALL of
these from \`twMergeConfig.generated.ts\` instead of the 7 hand-picked ones
above): \`colors\` (custom cog-* stops beyond what tailwind-merge's default
color-scale heuristics already catch), \`fontFamily\`, \`borderRadius\`,
\`backdropBlur\`, \`transitionDuration\`, \`transitionTimingFunction\`,
\`minHeight\`, \`animation\`.
`;
}


--- frontends/design-tokens/lib/emit-tailwind-preset.mjs (68 lines) ---
// Emits frontends/ui/tailwind.preset.ts's exact text from tokens.json.
//
// `preset-template.json` (checked in alongside this file) is a one-time
// mechanical split of the CURRENT preset file into alternating static-text
// segments and { path } references, built by
// `frontends/design-tokens/tools/build-preset-template.mjs` — see that
// script's header. Prose/comments/JS structure (keyframes, animation
// shorthand, the module wrapper) is not something DTCG models, so it stays
// static template text; every actual VALUE (every hex color, every px/ms/
// duration, every dimension) is a `{ path }` reference resolved against the
// LOADED tokens.json at generation time. Edit a value in tokens.json and
// regenerating changes the preset; edit the prose and you're editing the
// template, which is the correct place for prose to live.
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const TEMPLATE_PATH = join(HERE, "preset-template.json");

function resolvePath(tokens, path) {
  const parts = path.split(".");
  let node = tokens;
  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];
    if (node == null || typeof node !== "object") {
      throw new Error(`Cannot resolve token path "${path}" — stopped at "${part}"`);
    }
    if ("$value" in node) {
      // Leaf reached with path segments left over: index into its composite
      // $value (an array — fontFamily — or an object — custom-fontSize).
      return parts.slice(i).reduce((v, key) => v[key], node.$value);
    }
    node = node[part];
  }
  if (node == null || typeof node !== "object" || !("$value" in node)) {
    throw new Error(`Token path "${path}" does not resolve to a leaf token`);
  }
  return node.$value;
}

export function loadPresetTemplate(path = TEMPLATE_PATH) {
  return JSON.parse(readFileSync(path, "utf8"));
}

/**
 * Reconstruct frontends/ui/tailwind.preset.ts's text from `tokens` (a loaded
 * tokens.json object). Every `{ type: "ref", path, literal }` segment is
 * resolved against `tokens` and re-quoted exactly as the original literal
 * was quoted (single- vs double-quote, or a bare numeric-index color key
 * needing no quotes at all around its VALUE — the value itself is always
 * inside quotes in this preset, so we just swap the value inside whatever
 * quote character the original literal used).
 */
export function emitTailwindPreset(tokens, template = loadPresetTemplate()) {
  const out = [];
  for (const seg of template) {
    if (seg.type === "static") {
      out.push(seg.text);
      continue;
    }
    const value = resolvePath(tokens, seg.path);
    const quote = seg.literal[0]; // '"' or "'"
    out.push(`${quote}${value}${quote}`);
  }
  return out.join("");
}


--- frontends/design-tokens/lib/emit-tokens-css.mjs (50 lines) ---
// Emits tokens.css — CSS custom properties for every LITERAL-valued token in
// tokens.json (brand/status/accent ramps, spacing, radii, shadows, motion,
// z-index). Theme-switchable tokens (cog-canvas, cog-surface, cog-text-*,
// cog-border, cog-divider, cog-focus, cog-warning DEFAULT, commons-accent)
// are deliberately EXCLUDED: their literal RGB triples are defined per-MFE in
// each MFE's own src/styles/index.css (light/dark blocks), not centrally —
// see frontends/shell-mfe/src/styles/index.css for the pattern. Emitting a
// single value for them here would just be wrong for every other MFE.
import { orderedEntries, leafValue } from "./tokens.mjs";

function cssColorGroup(tokens, groupName) {
  const group = tokens.color.cog[groupName];
  return orderedEntries(group).map(
    ([key, node]) => `  --cog-${groupName}-${key}: ${leafValue(node)};`,
  );
}

function cssScalarGroup(prefix, group) {
  return orderedEntries(group).map(([key, node]) => `  --${prefix}-${key}: ${leafValue(node)};`);
}

export function emitTokensCss(tokens) {
  const lines = [];
  lines.push("/* GENERATED FILE — do not hand-edit.");
  lines.push(" * Produced by frontends/design-tokens/generate.mjs from tokens.json.");
  lines.push(" * Theme-switchable tokens (canvas/surface/text/border/divider/focus/");
  lines.push(" * warning-DEFAULT/commons-accent) are intentionally absent — their literal");
  lines.push(" * values are defined per-MFE in src/styles/index.css, not here. */");
  lines.push(":root {");
