// ---------------------------------------------------------------------------
// emit-colors-ts.mjs — a TypeScript colour map for RUNTIME consumers.
//
// Canvas, WebGL and inline-SVG code cannot use a utility class: it hands colour
// STRINGS to a drawing API. Those call sites previously hardcoded hex, which is
// token drift no gate could see — a ramp could be recoloured in tokens.json and
// the canvas would keep painting the old value forever.
//
// Two shapes come out of here:
//   * a LITERAL token (`cog-blue-600`) emits its hex directly;
//   * a THEME-AWARE token (`cog-surface`, whose $value is an
//     `rgb(var(--…))` reference) emits an explicit `{ light, dark }` pair,
//     because a canvas has no CSS cascade to resolve the var against — the
//     consumer must pick a side from its own theme state.
// ---------------------------------------------------------------------------
import { orderedEntries } from "./tokens.mjs";

function hexFromTriple(triple) {
  const [r, g, b] = triple.trim().split(/\s+/).map((n) => Number(n));
  const h = (n) => n.toString(16).toUpperCase().padStart(2, "0");
  return `#${h(r)}${h(g)}${h(b)}`;
}

/** Walk color.* and flatten to `cog-…` / `gc-…` / `kn-et-…` utility names. */
function collect(node, prefix, out) {
  for (const [key, child] of orderedEntries(node)) {
    if (child && typeof child === "object" && "$value" in child) {
      const name = prefix ? `${prefix}-${key}` : key;
      const value = child.$value;
      if (typeof value === "string" && value.startsWith("rgb(var(")) {
        const tv = child.$themeValues;
        if (tv?.light && tv?.dark) {
          out.push([name, { light: hexFromTriple(tv.light), dark: hexFromTriple(tv.dark) }]);
        }
        continue; // a var with no theme values has nothing a canvas can use
      }
      if (typeof value === "string") out.push([name, value]);
      continue;
    }
    if (child && typeof child === "object") {
      collect(child, prefix ? `${prefix}-${key}` : key, out);
    }
  }
}

export function emitColorsTs(tokens) {
  const out = [];
  const colors = tokens.color ?? {};
  for (const [group, node] of orderedEntries(colors)) {
    // `color.cog.*` flattens to the `cog-` utility prefix; sibling groups
    // (gc, knEt) already carry their prefix in the leaf key.
    // `color.cog.*` flattens to the `cog-` utility prefix. A sibling group
    // whose leaves already carry their own prefix (gc-*, kn-et-*) must NOT
    // gain a second one, but `commons` does need its group name or its
    // leaves collide with unprefixed keys.
    const firstLeaf = orderedEntries(node)[0]?.[0] ?? "";
    const carriesOwnPrefix = /^(gc|kn)-/.test(firstLeaf);
    collect(node, group === "cog" ? "cog" : carriesOwnPrefix ? "" : group, out);
