    .map(([name, v]) =>
      typeof v === "string"
        ? `  ${JSON.stringify(name)}: ${JSON.stringify(v)},`
        : `  ${JSON.stringify(name)}: { light: ${JSON.stringify(v.light)}, dark: ${JSON.stringify(v.dark)} },`,
    )
    .join("\n");
  return `// GENERATED by frontends/design-tokens/generate.mjs — do not edit.
//
// Runtime colour map for consumers that cannot use a utility class (canvas,
// WebGL, inline SVG attributes). A theme-aware token is emitted as an explicit
// { light, dark } pair: a canvas has no cascade to resolve rgb(var(--…)).
