import { contrastRatio } from "./contrast-math.mjs";

const HEX_RE = /^#[0-9a-fA-F]{6}$/;

function rate(ratio) {
  return {
    ratio: Math.round(ratio * 100) / 100,
    aaNormalText: ratio >= 4.5,
    aaLargeText: ratio >= 3,
    aaaNormalText: ratio >= 7,
  };
}

export function emitContrast(tokens) {
  const pairs = [];
  for (const [rampName, ramp] of Object.entries(tokens.color.cog)) {
    if (rampName.startsWith("$")) continue;
    if (!ramp || typeof ramp !== "object" || "$value" in ramp) continue; // skip non-ramp leaves
    for (const [stop, node] of orderedEntries(ramp)) {
      const value = leafValue(node);
      if (!HEX_RE.test(value)) continue; // skip CSS-var-backed leaves (DEFAULT, etc.)
      const token = `cog-${rampName}-${stop}`;
      pairs.push({
        token,
        hex: value,
        onWhite: rate(contrastRatio(value, "#FFFFFF")),
        onBlack: rate(contrastRatio(value, "#000000")),
      });
