    n += countLeaves(value);
  }
  return n;
}

function walkGroups(node, path, out) {
  if (isLeaf(node)) return;
  const entries = orderedEntries(node);
  const leafEntries = entries.filter(([, v]) => isLeaf(v));
  if (leafEntries.length > 0) {
    out.push({
      path: path.join("."),
      leafCount: leafEntries.length,
      types: [...new Set(leafEntries.map(([, v]) => v.$type))],
    });
  }
  for (const [key, value] of entries) {
    if (!isLeaf(value)) walkGroups(value, [...path, key], out);
  }
}

export function emitManifest(tokens) {
  const groups = [];
  for (const topKey of Object.keys(tokens)) {
    if (topKey.startsWith("$")) continue;
    walkGroups(tokens[topKey], [topKey], groups);
  }
  return {
    $schema: "cogos-design-tokens-manifest@1",
    source: "frontends/design-tokens/tokens.json",
    generatedBy: "frontends/design-tokens/generate.mjs",
    totalLeafTokens: countLeaves(tokens),
    groups,
  };
}


