// Emits frontends/ui/tailwind.preset.ts's exact text from tokens.json.
//
// `preset-template.json` (checked in alongside this file) is a one-time
// mechanical split of the CURRENT preset file into alternating static-text
// segments and { path } references, built by
// `frontends/design-tokens/tools/build-preset-template.mjs` — see that
// script's header. Prose/comments/JS structure (keyframes, animation
// shorthand, the module wrapper) is not something DTCG models, so it stays
// static template text; every actual VALUE (every hex color, every px/ms/
// duration, every dimension) is a `{ path }` reference resolved against the
// LOADED tokens.json at generation time. Edit a value in tokens.json and
// regenerating changes the preset; edit the prose and you're editing the
// template, which is the correct place for prose to live.
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const TEMPLATE_PATH = join(HERE, "preset-template.json");

function resolvePath(tokens, path) {
  const parts = path.split(".");
  let node = tokens;
  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];
    if (node == null || typeof node !== "object") {
      throw new Error(`Cannot resolve token path "${path}" — stopped at "${part}"`);
    }
    if ("$value" in node) {
      // Leaf reached with path segments left over: index into its composite
      // $value (an array — fontFamily — or an object — custom-fontSize).
      return parts.slice(i).reduce((v, key) => v[key], node.$value);
    }
    node = node[part];
  }
  if (node == null || typeof node !== "object" || !("$value" in node)) {
    throw new Error(`Token path "${path}" does not resolve to a leaf token`);
  }
  return node.$value;
}

export function loadPresetTemplate(path = TEMPLATE_PATH) {
  return JSON.parse(readFileSync(path, "utf8"));
}

/**
 * Reconstruct frontends/ui/tailwind.preset.ts's text from `tokens` (a loaded
 * tokens.json object). Every `{ type: "ref", path, literal }` segment is
 * resolved against `tokens` and re-quoted exactly as the original literal
 * was quoted (single- vs double-quote, or a bare numeric-index color key
 * needing no quotes at all around its VALUE — the value itself is always
 * inside quotes in this preset, so we just swap the value inside whatever
 * quote character the original literal used).
 */
export function emitTailwindPreset(tokens, template = loadPresetTemplate()) {
  const out = [];
  for (const seg of template) {
    if (seg.type === "static") {
      out.push(seg.text);
      continue;
    }
    const value = resolvePath(tokens, seg.path);
    const quote = seg.literal[0]; // '"' or "'"
    out.push(`${quote}${value}${quote}`);
  }
  return out.join("");
}


