// Emits tokens.css — CSS custom properties for every LITERAL-valued token in
// tokens.json (brand/status/accent ramps, spacing, radii, shadows, motion,
// z-index). Theme-switchable tokens (cog-canvas, cog-surface, cog-text-*,
// cog-border, cog-divider, cog-focus, cog-warning DEFAULT, commons-accent)
// are deliberately EXCLUDED: their literal RGB triples are defined per-MFE in
// each MFE's own src/styles/index.css (light/dark blocks), not centrally —
// see frontends/shell-mfe/src/styles/index.css for the pattern. Emitting a
// single value for them here would just be wrong for every other MFE.
import { orderedEntries, leafValue } from "./tokens.mjs";

function cssColorGroup(tokens, groupName) {
  const group = tokens.color.cog[groupName];
  return orderedEntries(group).map(
    ([key, node]) => `  --cog-${groupName}-${key}: ${leafValue(node)};`,
  );
}

function cssScalarGroup(prefix, group) {
  return orderedEntries(group).map(([key, node]) => `  --${prefix}-${key}: ${leafValue(node)};`);
}

export function emitTokensCss(tokens) {
  const lines = [];
  lines.push("/* GENERATED FILE — do not hand-edit.");
  lines.push(" * Produced by frontends/design-tokens/generate.mjs from tokens.json.");
  lines.push(" * Theme-switchable tokens (canvas/surface/text/border/divider/focus/");
  lines.push(" * warning-DEFAULT/commons-accent) are intentionally absent — their literal");
  lines.push(" * values are defined per-MFE in src/styles/index.css, not here. */");
  lines.push(":root {");
  for (const name of ["blue", "amber", "teal", "violet", "sky", "orange", "pink", "success", "green", "warning", "danger", "info"]) {
    lines.push(...cssColorGroup(tokens, name));
  }
  lines.push(`  --cog-border-dark-emphasized: ${tokens.color.cog["border-dark-emphasized"].$value};`);
  lines.push(...cssScalarGroup("cog-spacing", tokens.dimension.spacing));
  lines.push(...cssScalarGroup("cog-width", tokens.dimension.width));
  lines.push(`  --cog-border-width-field: ${tokens.dimension.borderWidth.field.$value};`);
  lines.push(...cssScalarGroup("cog-radius", tokens.dimension.borderRadius));
  lines.push(...cssScalarGroup("cog-min-height", tokens.dimension.minHeight));
  lines.push(...cssScalarGroup("cog-min-width", tokens.dimension.minWidth));
  lines.push(...cssScalarGroup("cog-backdrop-blur", tokens.dimension.backdropBlur));
  lines.push(...cssScalarGroup("cog-shadow", tokens.shadow.cog));
  lines.push(...cssScalarGroup("cog-gradient", tokens.gradient.cog));
  lines.push(...cssScalarGroup("cog-duration", tokens.motion.duration));
  lines.push(`  --cog-easing-emphasis: ${tokens.motion.easing.emphasis.$value};`);
  lines.push(...cssScalarGroup("cog-z", tokens.zIndex.cog));
  lines.push("}");
  lines.push("");
  return lines.join("\n");
}


