// Shared DTCG token loading/traversal helpers. Stdlib only.
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const HERE = dirname(fileURLToPath(import.meta.url));
export const TOKENS_PATH = join(HERE, "..", "tokens.json");

const META_KEYS = new Set(["$type", "$value", "$description", "$extensions"]);

export function loadTokens(path = TOKENS_PATH) {
  return JSON.parse(readFileSync(path, "utf8"));
}

function isLeaf(node) {
  return node && typeof node === "object" && ("$value" in node || "$type" in node);
}

/**
 * Return [key, node] pairs for a token GROUP (an object of leaf tokens or
 * nested groups), in emission order. A group with `$extensions.order` uses
 * that explicit order (needed because plain JS object key order hoists
 * integer-like keys like "50"/"300" before string keys like "DEFAULT" even
 * when "DEFAULT" is listed first in tokens.json / must render first in the
 * generated file — e.g. cog-warning). A group without `$extensions.order`
 * falls back to Object.keys() insertion order.
 */
export function orderedEntries(group) {
  const order = group?.$extensions?.order;
  const keys = order ?? Object.keys(group).filter((k) => !k.startsWith("$"));
  return keys.map((k) => [k, group[k]]);
}

export function leafValue(node) {
  if (!isLeaf(node)) throw new Error(`Not a leaf token: ${JSON.stringify(node)}`);
  return node.$value;
}

export function leafDescription(node) {
  return isLeaf(node) ? node.$description : undefined;
}

/**
 * Recursively validate DTCG shape: every leaf (an object carrying `$value`)
 * must also carry `$type`; every non-leaf, non-meta key must be a plain
 * object (a nested group). Returns a list of human-readable problems
 * (empty = valid).
 */
export function validateShape(node, path = "$") {
  const problems = [];
  if (node === null || typeof node !== "object" || Array.isArray(node)) {
    problems.push(`${path}: expected an object group or leaf token`);
    return problems;
  }
  if (isLeaf(node)) {
    if (typeof node.$type !== "string" || node.$type.length === 0) {
      problems.push(`${path}: leaf token missing $type`);
    }
    if (node.$value === undefined) {
      problems.push(`${path}: leaf token missing $value`);
    }
    return problems;
  }
  for (const [key, value] of Object.entries(node)) {
    if (META_KEYS.has(key)) continue;
    if (key.startsWith("$")) {
      problems.push(`${path}.${key}: unknown top-level meta key`);
      continue;
    }
    problems.push(...validateShape(value, `${path}.${key}`));
  }
  return problems;
}



